import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.DHmNT4rz.js";const u=JSON.parse('{"title":"Development guide","description":"","frontmatter":{},"headers":[],"relativePath":"develop/index.md","filePath":"develop/index.md","lastUpdated":1784470733000}'),i={name:"develop/index.md"};function r(s,e,l,d,c,h){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="development-guide" tabindex="-1">Development guide <a class="header-anchor" href="#development-guide" aria-label="Permalink to &quot;Development guide&quot;">​</a></h1><p>SaaSWeave ships the same repo-specific guidance its maintainers and coding agents work from. These pages document the current preferred way to build things in this codebase, from transport and state to logging and tests. They are mirrored from the <code>.agents/</code> directory in the repository, which stays the single source of truth.</p><p>Open the most specific page first, then follow its links only when a task crosses into another concern.</p><h2 id="working-in-the-codebase" tabindex="-1">Working in the codebase <a class="header-anchor" href="#working-in-the-codebase" aria-label="Permalink to &quot;Working in the codebase&quot;">​</a></h2><ul><li><a href="/SaaSWeave/develop/workflow">Workflow</a>: fix cadence, validation scope, build checks, migrations, commits.</li><li><a href="/SaaSWeave/develop/vite-plus">Vite Plus toolchain</a>: <code>vp</code> and <code>vpx</code>, workspace scripts, package management.</li><li><a href="/SaaSWeave/develop/typescript">TypeScript conventions</a>: typing rules and patterns used throughout the repo.</li><li><a href="/SaaSWeave/develop/testing">Testing</a>: focused unit and end-to-end coverage and test command scope.</li></ul><h2 id="backend" tabindex="-1">Backend <a class="header-anchor" href="#backend" aria-label="Permalink to &quot;Backend&quot;">​</a></h2><ul><li><a href="/SaaSWeave/develop/core">Core contracts</a>: pure shared contracts and security limits.</li><li><a href="/SaaSWeave/develop/environment-variables">Environment variables</a>: validated configuration schemas.</li><li><a href="/SaaSWeave/develop/auth">Auth patterns</a>: Better Auth on the server, client, and SSR.</li><li><a href="/SaaSWeave/develop/orpc">oRPC patterns</a>: procedures, routers, and client integration.</li><li><a href="/SaaSWeave/develop/api-fetching-patterns">API fetching patterns</a>: query and mutation conventions.</li><li><a href="/SaaSWeave/develop/logging">Logging</a>: durable logs, request logging, redaction.</li><li><a href="/SaaSWeave/develop/media-storage">Media storage</a>: uploads, delivery, and storage lifecycle.</li><li><a href="/SaaSWeave/develop/end-to-end-features">End-to-end features</a>: how a feature threads through every layer.</li></ul><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><ul><li><a href="/SaaSWeave/develop/tanstack-patterns">TanStack patterns</a>: Router and Query usage in the web app.</li><li><a href="/SaaSWeave/develop/zustand">Zustand state</a>: client state stores and conventions.</li><li><a href="/SaaSWeave/develop/ui">UI components</a>: the shared component library and theme tokens.</li><li><a href="/SaaSWeave/develop/i18n">Internationalization</a>: Paraglide messages and localized routing.</li><li><a href="/SaaSWeave/develop/seo">SEO</a>: route metadata helpers.</li></ul><h2 id="agent-skills" tabindex="-1">Agent skills <a class="header-anchor" href="#agent-skills" aria-label="Permalink to &quot;Agent skills&quot;">​</a></h2><p>The repository packages a couple of task-scoped playbooks as agent skills under <code>.agents/skills/</code>. Each skill is a thin activation wrapper (when to use it and a short procedure); the durable knowledge lives in reference docs that read as standalone engineering guides. Those reference docs are below.</p><ul><li><a href="/SaaSWeave/develop/skills/feature-building">Building a feature end-to-end</a>: every cross-cutting surface a new toggleable feature touches, with the concrete repo pattern for each.</li><li><a href="/SaaSWeave/develop/skills/redis-cache-jobs">Redis, queues, and caching</a>: package boundaries and the cache, queue, and retention patterns.</li></ul>',12)])])}const g=a(i,[["render",r]]);export{u as __pageData,g as default};
